/* Project ladders for the cloud & security platform topics. */
const TP5 = [
/* ---------- Azure ---------- */
{id:"t-azure-1",topic:"t-azure",lvl:1,title:"Map an Azure estate and its owners",hours:"2–3 hours",
 company:"Kavach IT Services, a 400-person Noida firm running client projects on Microsoft 365 and Azure.",
 problem:"A client audit asks: 'Describe how your Azure environment is organised, which regions hold client data, and who can change it.' Nobody has written this down. You have this export:",
 objective:"Write a one-page plain-English description of the Azure structure, data locations and access, and flag three things an auditor would question.",
 deliverables:["A tree diagram or indented list: tenant → subscriptions → resource groups → key resources","A table of resources holding client data with their region","Three flagged concerns with one-line reasons"],
 steps:[["Draw the hierarchy","Start with the tenant, then each subscription, then resource groups, then resources. Indented text is fine."],["Mark where client data lives","Databases and storage accounts usually hold data; web apps and networks usually don't. Note each one's region."],["Read the role assignments","Owner can change everything and grant access; Contributor can change; Reader can only look. Count Owners."],["Spot the concerns","Look for data outside India, too many Owners, guest accounts with high access, and test resources holding real data."],["Write it for a non-technical reader","Short sentences. Define 'subscription' once."]],
 data:{"Azure export":[["Subscription","Resource group","Resource","Type","Region"],["Kavach-Prod","client-portal","portal-web","App Service","Central India"],["Kavach-Prod","client-portal","portal-sql","SQL Database","Central India"],["Kavach-Prod","backups","kavachbackup01","Storage account","West Europe"],["Kavach-Dev","sandbox","test-sql","SQL Database","Central India"],["Kavach-Dev","sandbox","dev-vm-03","Virtual machine","South India"]],
  "Role assignments":[["Person","Role","Scope"],["CTO","Owner","Kavach-Prod"],["IT Manager","Owner","Kavach-Prod"],["Dev Lead","Owner","Kavach-Prod"],["vendor.consultant@outsourcer.com (guest)","Contributor","Kavach-Prod"],["Developers group (22)","Contributor","Kavach-Dev"],["Auditors group","Reader","Kavach-Prod"]],
  "Note from IT":[["Note"],["test-sql was loaded with a copy of last month's real client database to test a bug fix."]]},
 rubric:[["Hierarchy correctly shows tenant, both subscriptions, resource groups and resources",1],["Identifies the backup storage account in West Europe as client data outside India",1],["Flags three Owners on Prod and/or the guest Contributor as an access concern",1],["Flags real client data in the Dev test database",0],["Written in plain English a client could follow",0]],
 hints:["Backups contain client data too. Where is kavachbackup01?","How many people can grant access to Prod? Is an outside consultant's account a guest?","Read the IT note: what is in test-sql?"],
 key:{approach:"Structure first, then data location, then access, then concerns. Auditors care about data residency, privileged access and real data in test environments.",
  sample:"Tenant: Kavach IT\n  Kavach-Prod: client-portal (portal-web, portal-sql – Central India); backups (kavachbackup01 – WEST EUROPE)\n  Kavach-Dev: sandbox (test-sql – Central India; dev-vm-03 – South India)\nConcerns: 1) Client backups stored in West Europe, which may breach client contracts or RBI-style localisation expectations. 2) Three Owners plus an external guest Contributor on Prod: too much standing privilege; move to PIM and remove or time-limit the guest. 3) Real client data copied into Dev, where 22 developers have Contributor: use masked data.",
  tips:["Always ask where backups go; they are the most forgotten copy.","Guest accounts with write access are a classic third-party risk."]},
 videos:[["Why: how Azure is organised","Azure tenant subscription resource group explained"],["How: read Azure role assignments","Azure RBAC role assignments portal tutorial"]]},

{id:"t-azure-2",topic:"t-azure",lvl:2,title:"Design Conditional Access and MFA rules",hours:"3–4 hours",
 company:"Kavach IT Services (same firm). A phishing attack last month took over a finance user's email.",
 problem:"Leadership wants 'MFA for everyone' without locking anyone out. Facts: 400 staff; 6 global admins; finance and HR use an outsourced payroll app via single sign-on; some staff work from client sites; an old scanner sends email using a shared account that can't do MFA; two break-glass emergency admin accounts exist.",
 objective:"Write a set of Conditional Access policies (in plain words) with a rollout plan, exclusions and how you'll prove it works.",
 deliverables:["4–6 policies written as: users → apps → conditions → grant/block","An exclusions table with reason, compensating control and review date","A rollout plan using report-only mode","Evidence list for the next audit"],
 steps:[["Start with the highest risk","Admins first: MFA (phishing-resistant if possible) every time."],["Cover everyone","All users, all cloud apps: require MFA, perhaps less often from compliant company devices."],["Block old sign-in methods","Legacy authentication can't do MFA; block it."],["Handle exceptions properly","Break-glass accounts and the scanner account are exceptions. Each needs a reason and a compensating control."],["Roll out safely","Report-only first, review sign-in logs for who would be blocked, communicate, then enforce in phases."],["Define evidence","What would you export to prove it works?"]],
 rubric:[["Separate stricter policy for admins",1],["Policy requiring MFA for all users on all cloud apps",1],["Legacy authentication blocked",1],["Exclusions documented with reason and compensating control (break-glass, scanner)",1],["Report-only rollout with log review before enforcement",0],["Evidence list (policy export, MFA registration report, sign-in logs)",0]],
 hints:["What can't do MFA at all? Old protocols and the scanner.","Break-glass accounts are excluded so you can't lock yourself out, but they must be monitored.","Report-only mode shows who would be affected before anyone is blocked."],
 key:{approach:"Risk-ordered policies, tight exceptions with compensations, safe rollout, then evidence. Reviewers look for the exclusions handling as much as the policies.",
  sample:"CA01 Admins: all admin roles → all apps → any location → require phishing-resistant MFA, sign-in frequency 4h.\nCA02 All users: all users (excl. break-glass, svc-scanner) → all cloud apps → require MFA; compliant devices remember for 7 days.\nCA03 Block legacy auth: all users → all apps → legacy clients → block.\nCA04 Payroll app: Finance+HR → payroll SSO app → require MFA + compliant device.\nExclusions: break-glass x2 – emergency access; compensating: long random passwords in sealed storage, alert on any sign-in, quarterly test. svc-scanner – device can't do MFA; compensating: restricted to office IP, can only send to internal domain, review 31 Mar.\nRollout: report-only 2 weeks → review sign-in logs → comms → enforce admins wk3, all wk4.\nEvidence: CA policy JSON export, MFA registration report, sign-in log sample showing MFA, exclusion register.",
  tips:["Never exclude a whole group 'for now'.","Alerting on break-glass sign-ins is what makes the exclusion safe."]},
 videos:[["Why: Conditional Access explained","Entra Conditional Access explained"],["How: report-only mode and rollout","Conditional Access report-only mode rollout"]]},

{id:"t-azure-3",topic:"t-azure",lvl:3,title:"Read a Defender for Cloud compliance report and build the remediation plan",hours:"5–6 hours",
 company:"PaySetu, a Bengaluru payments start-up preparing for ISO 27001 certification on Azure.",
 problem:"The Defender for Cloud regulatory compliance view for ISO 27001 shows these failing assessments. The CTO asks: 'Which matter for the audit, who fixes what, and what do we tell the auditor about the rest?'",
 objective:"Prioritise the failing items, map them to ISO 27001 Annex A controls, assign owners and dates, and justify any you propose to accept.",
 deliverables:["A remediation table: finding, ISO control, risk, priority, owner, due date, evidence of fix","Up to two justified risk acceptances","A half-page note to the CTO on audit impact"],
 steps:[["Understand each finding","Rewrite each in one plain sentence: what is wrong and what could happen."],["Map to ISO 27001","Use Annex A: access (5.15–5.18, 8.2, 8.5), logging (8.15–8.16), cryptography (8.24), vulnerabilities (8.8), backup (8.13), network security (8.20–8.22)."],["Prioritise","Internet exposure and customer data first."],["Assign","Owner job title, realistic dates before the Stage 2 audit."],["Decide what to accept","Only low-risk items with a clear reason and approval."],["Write the CTO note","What blocks certification, what doesn't, what the auditor will ask."]],
 data:{"Failing assessments":[["#","Assessment","Affected resources"],["1","MFA should be enabled for accounts with owner permissions","3 accounts"],["2","Storage accounts should restrict network access","2 (incl. kyc-docs)"],["3","SQL databases should have vulnerability findings resolved","1 (payments-db, 2 High)"],["4","Diagnostic logs should be enabled for Key Vault","1"],["5","Management ports of VMs should be protected with just-in-time access","1 (jump-vm, RDP open to internet)"],["6","Azure Backup should be enabled for virtual machines","1 (build-agent, rebuilt from code)"],["7","Endpoint protection should be installed on machines","1 (build-agent)"]]},
 rubric:[["Each finding mapped to a relevant ISO 27001 Annex A control",1],["Owner MFA, open RDP and the public KYC storage prioritised highest",1],["Owners and dates for every item",1],["Any risk acceptance limited to genuinely low-risk items with reason and approver",0],["CTO note distinguishes certification blockers from improvements",0],["Evidence of fix defined for each item",0]],
 hints:["Which findings are reachable from the internet or protect customer data?","Backup for a machine rebuilt from code may be a reasonable acceptance. Endpoint protection probably isn't.","Auditors look for a managed process: known gaps with owners and dates are better than hidden ones."],
 key:{approach:"Translate, map, prioritise by exposure and data, assign, accept sparingly, and communicate audit impact. Certification auditors accept open items if they are risk-assessed and tracked; they don't accept unmanaged critical gaps.",
  sample:"P1 (7 days): #1 Owner MFA – A.8.5/A.5.17 – Cloud Lead; evidence: CA policy + registration report. #5 RDP open – A.8.20/A.8.22 – Infra Lead; enable JIT/close port; evidence: NSG rule export. #2 kyc-docs network access – A.8.20/A.5.15 – Cloud Lead; private endpoint.\nP2 (30 days): #3 payments-db Highs – A.8.8 – DBA. #4 Key Vault logs – A.8.15 – Security Eng. #7 Endpoint protection on build-agent – A.8.7 – IT.\nAccept: #6 Backup on build-agent – A.8.13 – rebuilt automatically from code in under an hour; no data stored; approved by CTO; review in 12 months.\nCTO note: #1, #2, #5 would be major findings if open at Stage 2. The rest are acceptable as tracked actions in the risk treatment plan.",
  tips:["Map to the 2022 Annex A numbering.","An acceptance without an approver and review date is a finding itself."]},
 videos:[["Why: secure score and compliance","Defender for Cloud secure score regulatory compliance explained"],["How: ISO 27001 Annex A 2022 controls","ISO 27001 2022 Annex A controls explained"]]},

/* ---------- AWS ---------- */
{id:"t-aws-1",topic:"t-aws",lvl:1,title:"Shared responsibility: who answers each question?",hours:"2 hours",
 company:"LedgerLeaf, a 60-person accounting SaaS hosted on AWS (Mumbai region).",
 problem:"A UK client's security questionnaire has 10 questions. For each, decide whether AWS or LedgerLeaf is responsible and where the evidence comes from.",
 objective:"Complete the questionnaire table with responsibility, evidence source and a one-line answer.",
 deliverables:["A 10-row table: question, responsible party, evidence source (AWS service or document), draft answer"],
 steps:[["Read each question","Physical things and AWS's hardware are AWS's. Settings, accounts and data are yours."],["Name the evidence","AWS's own reports come from AWS Artifact. Your settings come from IAM, CloudTrail, Config, S3 settings."],["Draft short answers","State facts you'd be able to prove; don't overclaim."]],
 data:{"Questions":[["#","Question"],["1","How are data centres physically secured?"],["2","Is MFA enforced for administrator access?"],["3","Are customer files encrypted at rest?"],["4","Are logs of administrator actions retained for 12 months?"],["5","Can you provide your hosting provider's SOC 2 report?"],["6","In which country is customer data stored?"],["7","How are servers' operating systems patched?"],["8","Are storage buckets prevented from public access?"],["9","How is hardware disposed of securely?"],["10","Who reviews user access, and how often?"]]},
 rubric:[["Questions 1, 5 and 9 assigned to AWS with AWS Artifact as evidence",1],["Questions 2, 3, 4, 8 and 10 assigned to LedgerLeaf with a named AWS service or document as evidence",1],["Q6 answered with the Mumbai region as LedgerLeaf's choice",0],["Q7 recognises OS patching on EC2 is the customer's job",1],["Answers are factual and not overclaimed",0]],
 hints:["Could LedgerLeaf change it from its own console? Then it's LedgerLeaf's.","AWS's SOC 2 report covers physical and hardware controls; find it in AWS Artifact.","Log retention depends on the CloudTrail trail and the bucket's lifecycle rule, which LedgerLeaf configures."],
 key:{approach:"Apply the line: of the cloud = AWS, in the cloud = customer. Evidence for AWS's side comes from AWS Artifact; evidence for your side comes from your own configuration and processes.",
  sample:"1 AWS – AWS SOC 2 (Artifact) – 'Our provider's data centres are covered by its SOC 2 report.' 2 LedgerLeaf – IAM Identity Center MFA setting/credential report. 3 LedgerLeaf – S3 default encryption + Config rule. 4 LedgerLeaf – CloudTrail + log bucket lifecycle (12 months). 5 AWS – Artifact. 6 LedgerLeaf – chose ap-south-1 Mumbai. 7 LedgerLeaf – patch schedule/SSM Patch Manager. 8 LedgerLeaf – S3 Block Public Access (account level). 9 AWS – Artifact (media sanitisation in SOC 2). 10 LedgerLeaf – quarterly access review record.",
  tips:["'AWS handles security' is never an acceptable answer.","Offer AWS's report under its terms; don't paste it into your own documents."]},
 videos:[["Why: shared responsibility","AWS shared responsibility model explained"],["How: AWS Artifact","AWS Artifact download SOC report"]]},

{id:"t-aws-2",topic:"t-aws",lvl:2,title:"Review IAM policies for least privilege",hours:"3 hours",
 company:"LedgerLeaf (same company).",
 problem:"Before a SOC 2 audit, you're asked to review four IAM policies attached to people and roles, and the IAM credential report summary.",
 objective:"For each policy, explain in plain words what it allows, whether that's too much, and the fix; then list findings from the credential report.",
 deliverables:["One paragraph per policy: what it allows, risk, recommended change","A findings table from the credential report with severity and owner"],
 steps:[["Read Effect, Action, Resource","Allow or Deny; which actions ('*' means all); which resources ('*' means all)."],["Compare with the job","Does an analyst need to delete buckets? Does billing need EC2?"],["Recommend specific changes","Name the actions and resources that should remain."],["Read the credential report","Look for root usage, missing MFA, old access keys, unused users."]],
 data:{"Policies":[["Name","Attached to","Policy (simplified)"],["P1","Data analyst","Allow s3:* on *"],["P2","Billing team","Allow aws-portal:ViewBilling on *; Allow ec2:* on *"],["P3","Deploy role (CI pipeline)","Allow * on *"],["P4","Support engineers","Allow s3:GetObject on arn:aws:s3:::ledgerleaf-logs/*; Deny s3:DeleteObject on *"]],
  "Credential report":[["User","Password last used","MFA","Access key age (days)","Notes"],["root","3 days ago","No","none",""],["amit.dev","today","Yes","410",""],["former.intern","120 days ago","No","200","left in June"],["svc-reports","n/a","n/a","95","used by reporting script"]]},
 rubric:[["P1 identified as far too broad (all actions on all buckets) with a narrower read-only fix",1],["P3 Allow * on * identified as the most dangerous, with scoped permissions recommended",1],["P2 ec2:* flagged as unrelated to billing",0],["P4 recognised as reasonable least privilege",0],["Root without MFA and recently used flagged as critical",1],["Former intern's active account and 410-day-old key flagged",0]],
 hints:["'*' in Action or Resource is the first thing to look for.","Why would the billing team change servers?","Root should have MFA and almost never be used. 3 days ago is a red flag."],
 key:{approach:"Read each policy literally, compare with job need, recommend specific scoped permissions; then treat the credential report as an access-review dataset.",
  sample:"P1: can read, change and delete every bucket. Analyst needs read on the analytics bucket only → s3:GetObject/ListBucket on that bucket. P2: billing view fine; ec2:* lets billing staff launch/terminate servers – remove. P3: full admin for a pipeline – if stolen, attacker owns the account; scope to the deploy actions and resources, add permission boundary. P4: read-only on logs plus explicit deny delete – good.\nFindings: root no MFA + used 3 days ago (Critical, CTO: enable MFA, investigate use, stop using root); former.intern active with old key (High, IT: disable now, delete key, check CloudTrail for use); amit.dev key 410 days (Medium, rotate, policy 90 days); svc-reports key 95 days (Low, rotate, move to role).",
  tips:["Explain risk as 'if this login were stolen, the attacker could…'.","Explicit Deny is a strong safety net; note it as good practice."]},
 videos:[["Why: least privilege in AWS","AWS IAM least privilege best practices"],["How: read IAM policies","how to read AWS IAM policy JSON"]]},

{id:"t-aws-3",topic:"t-aws",lvl:3,title:"Build an AWS evidence pack for SOC 2",hours:"5–6 hours",
 company:"LedgerLeaf, starting a SOC 2 Type II observation window next month.",
 problem:"The auditor sent a request list covering logical access, change management, logging and monitoring, encryption, and vendor management for AWS. You need a plan for how each control will be evidenced from AWS services for the whole period, not just one day.",
 objective:"Produce a control-to-evidence matrix for 10 AWS-related SOC 2 controls naming the AWS service, the exact artefact, the frequency and the owner, plus the setup needed before the window starts.",
 deliverables:["A 10-row matrix: SOC 2 criterion, control in plain words, AWS service, evidence artefact, frequency, owner","A pre-window setup checklist (things to switch on now)","Three risks to the audit and how you'll manage them"],
 steps:[["Pick 10 controls","Cover CC6 (access), CC7 (monitoring), CC8 (change), CC6.7/CC6.1 (encryption), CC9 (vendors)."],["Choose evidence that persists","Config rule history and CloudTrail cover a period; a screenshot covers a moment."],["Set up before the window","CloudTrail org trail to a locked log account, Config recorder and conformance pack, Security Hub standard, billing and root alarms."],["Plan recurring evidence","Quarterly access reviews, monthly Security Hub exports, change tickets linked to deployments."],["Name risks","Gaps in logging, manual steps missed, scope creep from new accounts."]],
 rubric:[["Ten controls with SOC 2 criterion references",1],["Evidence named as specific AWS artefacts (e.g. Config rule history, CloudTrail, IAM credential report, Security Hub export, AWS Artifact SOC 2)",1],["Distinguishes point-in-time from period evidence and prefers period evidence",1],["Pre-window setup checklist includes logging and Config before the window starts",1],["Owners and frequencies given",0],["Realistic audit risks with mitigations",0]],
 hints:["A Type II auditor samples across months; what proves the control every day?","If CloudTrail starts mid-window, what happens to the earlier months?","Vendor management: where does AWS's own SOC 2 come from, and who reviews it each year?"],
 key:{approach:"Control → AWS evidence source → persistence over the window → setup before day one → recurring manual evidence → risks. Reviewers reward period evidence and preparation.",
  sample:"CC6.1 MFA for console access | IAM Identity Center + Config rule mfa-enabled | rule history (continuous) | Cloud Lead\nCC6.2 Joiners/leavers | HR ticket + Identity Center user list | per event, monthly reconcile | IT\nCC6.3 Quarterly access review | exported permission sets signed by managers | quarterly | GRC\nCC6.1 Encryption at rest | Config s3-default-encryption, rds-storage-encrypted | continuous | Cloud Lead\nCC6.6 No public buckets | S3 Block Public Access + Config | continuous\nCC7.2 Threat monitoring | GuardDuty findings + triage tickets | continuous/weekly | Security\nCC7.2 Logging | org CloudTrail to log-archive account, 1-year lifecycle | continuous\nCC7.1 Config baseline | Security Hub FSBP score export | monthly\nCC8.1 Changes | PR approvals + deployment pipeline logs | per change\nCC9.2 Vendor review | AWS SOC 2 from Artifact reviewed | annually | GRC\nSetup now: org trail, Config + conformance pack, Security Hub, root MFA + alarm, ticket templates.",
  tips:["Turn everything on before the window, then don't change scope casually.","Keep a short 'how to pull this evidence' note per control."]},
 videos:[["Why: SOC 2 Type II explained","SOC 2 Type 2 explained observation period"],["How: AWS Config and Security Hub for compliance","AWS Config conformance pack Security Hub compliance demo"]]},

/* ---------- Purview ---------- */
{id:"t-purview-1",topic:"t-purview",lvl:1,title:"Design a sensitivity label scheme",hours:"2–3 hours",
 company:"Kavach IT Services, holding client source code, employee HR files and customer personal data in Microsoft 365.",
 problem:"The DPO wants labels so staff know how to handle documents. Too many labels and nobody uses them; too few and they mean nothing.",
 objective:"Propose 4–5 labels with plain-English definitions, examples, protections and who can apply or remove them.",
 deliverables:["A label table: name, meaning, examples, protection (marking/encryption/sharing limits), default or auto-apply","Five sample documents labelled with reasons","A short rollout note for staff"],
 steps:[["Start from the classification policy","Public / Internal / Confidential / Restricted is a common base."],["Define each in one line","What harm if it leaked?"],["Add protections","Headers and watermarks for Confidential; encryption limited to named groups for Restricted."],["Decide automation","Default label for new documents; auto-suggest when PAN or Aadhaar-like numbers appear."],["Explain to staff","One paragraph and examples."]],
 rubric:[["4–5 labels with clear, distinct meanings",1],["Examples and protections per label, with encryption only where justified",1],["Five sample documents labelled correctly with reasons",1],["Default and auto-labelling proposed sensibly",0],["Staff note in plain English",0]],
 hints:["Ask for each label: what's the harm if it leaked?","Encrypting everything causes problems with partners and search; reserve it for Restricted.","Auto-label suggestions work well for patterns like PAN numbers."],
 key:{approach:"Few labels, each defined by harm, with protections matching the harm, sensible defaults, and staff guidance.",
  sample:"Public – approved for anyone – press release – none.\nInternal (default) – staff only, low harm – org chart – footer 'Internal'.\nConfidential – harm if leaked – client contracts, source code – header + watermark, block anonymous links.\nConfidential – Personal data – contains customer/employee personal data – watermark, external sharing warning, DLP applies; auto-suggest when PAN/Aadhaar patterns found.\nRestricted – severe harm – HR investigations, encryption keys, M&A – encrypted to named group, no forwarding.\nSamples: salary file → Restricted; client SOW → Confidential; KYC export → Confidential – Personal data…",
  tips:["Name labels the way staff talk.","A sub-label for personal data links labels directly to DPDP/GDPR duties."]},
 videos:[["Why: sensitivity labels","Microsoft Purview sensitivity labels explained"],["How: label policy setup","create sensitivity label policy Purview tutorial"]]},

{id:"t-purview-2",topic:"t-purview",lvl:2,title:"Write and tune a DLP policy",hours:"3–4 hours",
 company:"PaySetu, a payments start-up on Microsoft 365, subject to DPDP and RBI expectations.",
 problem:"Customer PAN numbers and card numbers sometimes leave by email. The CISO wants a DLP policy. A two-week simulation produced these matches:",
 objective:"Write the DLP policy (conditions, actions, exceptions), then use the simulation results to tune it before enforcement.",
 deliverables:["Policy in plain words: locations, conditions, thresholds, actions, user notifications, incident reports","Analysis of the simulation results with tuning decisions","Enforcement plan and metrics to monitor"],
 steps:[["Pick locations","Exchange email, SharePoint, OneDrive, Teams, devices."],["Define conditions","Sensitive types (PAN, credit card) with counts and confidence; external recipients."],["Choose actions by severity","Low volume: warn with policy tip and allow justification; high volume: block and alert."],["Read the simulation","Which matches were real problems, which were false positives?"],["Tune","Allow-list the statutory auditor's domain? Raise threshold? Exclude test data?"],["Plan enforcement and metrics","Phased; track overrides and false positives."]],
 data:{"Simulation results (2 weeks)":[["Pattern","Matches","Destination","Reviewed outcome"],["PAN 1–9 per email","142","Customers (their own PAN in a receipt)","Legitimate business"],["PAN 10+ per email","6","Personal Gmail addresses of 2 staff","Real risk"],["Card numbers 1+","38","Payment processor partner domain","Legitimate, contract in place"],["Card numbers 1+","4","Unknown external domains","Real risk"],["PAN 10+ per email","11","Statutory auditor's domain","Legitimate, audit"],["Card number pattern","57","Internal test files with fake numbers","False positive"]]},
 rubric:[["Policy defines locations, sensitive types, thresholds and external-recipient condition",1],["Graduated actions (warn/justify vs block) by volume or risk",1],["Correctly identifies the personal-Gmail and unknown-domain matches as real risks",1],["Tuning handles auditor and processor domains and test-data false positives without opening a broad hole",1],["Phased enforcement with metrics (matches, overrides, false positive rate)",0]],
 hints:["Customers receiving their own PAN is expected; blocking that breaks the business.","Allow specific partner domains under contract, not 'all external'.","Fake test numbers: can they be excluded by location or by better confidence settings?"],
 key:{approach:"Policy → simulate → separate real risk from business-as-usual and false positives → tune narrowly → enforce in phases → measure.",
  sample:"Locations: Exchange, OneDrive, SharePoint, Teams, endpoints.\nRule A (high): PAN ≥10 or card ≥1, recipient outside org and not on allowed-partners list → block, notify user and privacy team, incident report.\nRule B (low): PAN 1–9 external → policy tip, allow with business justification.\nTuning: add processor and statutory-auditor domains to allowed-partners (reviewed quarterly, contract linked); exclude the test-data site, use high-confidence card detection (Luhn-validated); personal email domains stay blocked.\nEnforce: Rule A week 1 for finance, all staff week 3. Metrics: weekly matches, overrides with reasons, false positives below 10%.",
  tips:["Every exception should have a contract and a review date.","Personal-email exfiltration is also an insider-risk signal."]},
 videos:[["Why: DLP explained","data loss prevention explained Microsoft Purview"],["How: DLP simulation mode","Purview DLP policy simulation mode tuning"]]},

{id:"t-purview-3",topic:"t-purview",lvl:3,title:"Answer a DSAR and set retention with Purview",hours:"5–6 hours",
 company:"Kavach IT Services. A former employee, Meera Iyer, has sent a DPDP access request and asked for her data to be erased.",
 problem:"Meera's data sits in mailboxes, Teams chats, HR SharePoint, payroll exports and an old recruitment folder. Kavach must also keep payroll and tax records for statutory periods, and there is a pending labour dispute with her.",
 objective:"Plan the eDiscovery search and response, decide what can be erased now versus kept (and why), and design retention so this is easier next time.",
 deliverables:["An eDiscovery search plan: locations, people, keywords, date ranges, exclusions","A response decision table: data set, provide?, erase?, legal reason","Retention policy proposal for HR data with periods and disposition review","A short reply letter to Meera in plain language"],
 steps:[["Scope the search","Her mailbox, colleagues' mailboxes mentioning her, Teams, HR and payroll sites. Use her name, email, employee ID."],["Check for holds","A pending dispute means a legal hold: erasure must wait."],["Separate provide vs erase","Access: give her personal data, not others' confidential information. Erasure: allowed only where no legal or legitimate reason to keep."],["Decide retention","Payroll and tax: statutory periods. Recruitment data of rejected candidates: short. HR files: after employment plus a set period."],["Write to Meera","What you're providing, what you can't erase yet and why, timeline, how to complain."]],
 rubric:[["Search plan covers all relevant locations with identifiers and date range",1],["Recognises the legal hold from the labour dispute prevents erasure of related data",1],["Distinguishes data retained under law (payroll/tax) from data that can be erased (old recruitment data)",1],["Protects third parties' information in the access response",0],["Retention proposal with periods and disposition review",0],["Clear, respectful reply letter with reasons and next steps",0]],
 hints:["Before deleting anything, ask: is anything under hold?","Access means her personal data, not every email that mentions her name in someone else's private matter.","Retention labels with disposition review let Legal approve deletions."],
 key:{approach:"Search → hold check → access response with redaction → erasure only where no legal basis remains → retention design to prevent future over-retention → transparent reply.",
  sample:"Search: mailboxes (Meera + HR + manager), Teams, HR site, payroll site, recruitment folder; terms: name, email, EMP-2214; 2021–2026.\nHold: dispute-related HR and manager communications placed on legal hold.\nProvide: HR file, payroll slips, appraisal summaries, her own emails/chats (third-party data redacted).\nErase: 2021 recruitment folder copies, marketing list entry, duplicate ID scans on old share.\nKeep: payroll and tax records (statutory), dispute materials (hold).\nRetention: HR records = employment + 7 years with disposition review; recruitment (unsuccessful) = 12 months then delete; payroll = statutory period.\nLetter: lists what's enclosed, what was deleted, what is kept and why, when the rest will be reviewed, grievance contact and Board complaint right.",
  tips:["Document every decision; DSAR handling is itself audited.","Never erase data under a legal hold, even if asked."]},
 videos:[["Why: DSARs with eDiscovery","Microsoft Purview eDiscovery data subject request"],["How: retention labels and disposition","Purview retention label disposition review tutorial"]]},

/* ---------- Sentinel ---------- */
{id:"t-sentinel-1",topic:"t-sentinel",lvl:1,title:"Read KQL queries and explain them",hours:"2 hours",
 company:"Kavach IT Services' security team uses Microsoft Sentinel. The ISO 27001 auditor wants to understand what the monitoring rules actually do.",
 problem:"You're given five KQL queries used as analytics rules. Explain each in plain English for the audit file, and say what attack it would catch and what it would miss.",
 objective:"Translate five queries into plain English with purpose, data source, logic, and one limitation each.",
 deliverables:["Five short explanations (purpose, table, logic, limitation)","A one-line mapping of each to ISO 27001 A.8.16 (monitoring) evidence"],
 steps:[["Name the table","The first word is the table: SigninLogs, AuditLogs, OfficeActivity…"],["Read each | step","where filters; summarize counts or groups; project picks columns; ago(1h) means 'in the last hour'."],["Say what it catches","Describe the attacker behaviour."],["Say what it misses","Thresholds, time windows and tables limit any rule."]],
 data:{"Queries":[["#","Query"],["Q1","SigninLogs | where ResultType != \"0\" | summarize Failures=count() by IPAddress, bin(TimeGenerated, 10m) | where Failures > 20"],["Q2","AuditLogs | where OperationName == \"Add member to role\" | where TargetResources has \"Global Administrator\""],["Q3","OfficeActivity | where Operation == \"New-InboxRule\" | where Parameters has \"ForwardTo\""],["Q4","SigninLogs | where ResultType == \"0\" | where Location !in (\"IN\") | project TimeGenerated, UserPrincipalName, Location, IPAddress"],["Q5","OfficeActivity | where Operation == \"FileDownloaded\" | summarize Files=count() by UserId, bin(TimeGenerated, 1h) | where Files > 500"]]},
 rubric:[["Each query's table and purpose correctly identified",1],["Q1 explained as many failed sign-ins from one IP in 10 minutes (password spraying/brute force)",1],["Q3 explained as mailbox forwarding rules (common after email account takeover)",1],["A sensible limitation for each (e.g. slow attacks under threshold, travelling staff)",0],["Plain English suitable for an audit file",0]],
 hints:["ResultType \"0\" means a successful sign-in in Entra logs.","bin(TimeGenerated, 10m) groups events into 10-minute buckets.","Attackers often set forwarding rules after taking over a mailbox."],
 key:{approach:"Table → filter → aggregate → threshold → what it catches → what it misses. Auditors want to know the rule exists, what it covers and how it's reviewed.",
  sample:"Q1: Sign-ins: counts failed logins per IP per 10 min; alerts above 20. Catches brute force/password spraying from one IP. Misses slow attacks (<20 per 10 min) and attacks spread across many IPs.\nQ2: Directory changes: anyone added to Global Administrator. Catches privilege escalation. Misses other powerful roles.\nQ3: Mailbox forwarding rules created. Catches data theft after account takeover. Misses forwarding set by admins via other methods.\nQ4: Successful sign-ins from outside India. Catches stolen credentials used abroad. Noisy for travelling staff; misses attackers using Indian VPNs.\nQ5: Users downloading 500+ files an hour. Catches bulk exfiltration. Misses slower theft.\nA.8.16: each rule is evidence of monitoring for a defined risk; review records needed too.",
  tips:["Always state a limitation; it shows judgement.","Pair every rule with who reviews its alerts."]},
 videos:[["Why: what SIEM rules do","SIEM detection rules explained"],["How: KQL basics","KQL tutorial beginners where summarize project"]]},

{id:"t-sentinel-2",topic:"t-sentinel",lvl:2,title:"Investigate an account takeover from logs",hours:"3–4 hours",
 company:"Kavach IT Services. A Sentinel incident fired at 02:20 for user m.rao.",
 problem:"You have extracts from three tables. Reconstruct what happened, decide whether personal data was affected, and draft the incident summary for the CISO and DPO.",
 objective:"Produce a timeline, scope, impact assessment and recommended next steps, including whether CERT-In and DPDP notification clocks apply.",
 deliverables:["A minute-by-minute timeline","Scope: accounts, IPs, data touched","Impact: personal data? reportable?","Recommended containment and follow-up actions","The KQL query you'd use to check for other affected users"],
 steps:[["Order events by time","Merge the three tables into one timeline."],["Identify the attacker","Which IP, from where, doing what?"],["Find what data was touched","File names, mailbox rules."],["Decide on reporting","Unauthorised access to personal data → DPDP breach; CERT-In reportable incident types include unauthorised access to systems/data."],["Hunt for more","Write a query: other sign-ins from the attacker IP."]],
 data:{"SigninLogs":[["Time","User","IP","Location","Result","App"],["01:40","m.rao","185.199.110.42","NL","Failure (bad password)","Office 365"],["01:41","m.rao","185.199.110.42","NL","Failure (bad password)","Office 365"],["02:14","m.rao","185.199.110.42","NL","Success (MFA by SMS)","Office 365"],["02:15","s.iyer","185.199.110.42","NL","Failure (bad password)","Office 365"],["09:02","m.rao","49.36.22.18","IN","Success","Office 365"]],
  "AuditLogs":[["Time","Actor","Operation","Target"],["02:16","m.rao","Update user – MFA method added","authenticator app (new device)"]],
  "OfficeActivity":[["Time","User","Operation","Detail"],["02:18","m.rao","New-InboxRule","Forward emails containing 'invoice' to ext.archive@protonmail.com"],["02:25","m.rao","FileDownloaded","clients_2026.xlsx (names, phone, PAN)"],["02:26","m.rao","FileDownloaded","payroll_oct.xlsx"]]},
 rubric:[["Correct timeline from failures through MFA, persistence and downloads",1],["Identifies attacker IP and that s.iyer was also targeted",1],["Recognises persistence (new MFA method and forwarding rule) needing removal",1],["Concludes personal data (client PAN, payroll) was accessed: DPDP breach assessment and CERT-In 6-hour reporting considered",1],["Containment actions: revoke sessions, reset password, remove MFA method and rule, block IP",0],["A sensible hunting query for other users",0]],
 hints:["What did the attacker do right after logging in to keep access?","Which downloaded files contain personal data?","SigninLogs | where IPAddress == \"…\" shows everyone that IP touched."],
 key:{approach:"Timeline → attacker → persistence → data impact → legal clocks → containment → hunt for more. Reviewers look for the persistence steps and the legal assessment.",
  sample:"01:40–01:41 failed logins from 185.199.110.42 (NL). 02:14 success with SMS MFA (likely SIM-swap or MFA fatigue/phish). 02:15 same IP tries s.iyer (failed). 02:16 attacker adds own authenticator (persistence). 02:18 forwarding rule to protonmail (persistence/exfiltration). 02:25–02:26 downloads clients_2026.xlsx (PAN, phones) and payroll_oct.xlsx. 09:02 real user logs in from India.\nImpact: client and employee personal data accessed and likely exfiltrated → personal data breach; intimate Data Protection Board and affected people per DPDP Rules; CERT-In report within 6 hours of noticing.\nContain: revoke sessions, reset password, remove rogue MFA method and inbox rule, block IP, check s.iyer, move users off SMS MFA.\nHunt: SigninLogs | where IPAddress == \"185.199.110.42\" | summarize count() by UserPrincipalName, ResultType",
  tips:["Persistence is the step beginners miss.","Note the clocks start when you became aware, not when the investigation ends."]},
 videos:[["Why: account takeover pattern","Microsoft 365 account compromise investigation inbox rule"],["How: investigating incidents in Sentinel","Microsoft Sentinel incident investigation walkthrough"]]},

{id:"t-sentinel-3",topic:"t-sentinel",lvl:3,title:"Logging and monitoring standard with detection coverage",hours:"6 hours",
 company:"PaySetu (payments start-up, RBI-regulated partner bank, CERT-In obligations, SOC 2 customers).",
 problem:"PaySetu has Sentinel with only Entra sign-in logs connected and two default rules. The board asks: 'Are we logging what the law and our customers require, and would we detect the attacks that matter?'",
 objective:"Write a logging and monitoring standard and a detection coverage plan: which sources, how long, which rules, who reviews, and how you'll prove it.",
 deliverables:["Log source inventory with retention (and where stored) and justification","At least 8 detection use cases mapped to attack steps, with data source and owner","Review and tuning process (who, how often, metrics)","Evidence plan for ISO 27001 A.8.15/A.8.16, SOC 2 CC7 and CERT-In"],
 steps:[["List required sources","Identity, Microsoft 365, cloud control plane (Azure/AWS), firewalls, servers, payment application, endpoint security."],["Set retention","CERT-In: 180 days within India; contracts and PCI DSS may require more; balance cost."],["Pick use cases","Use the attack chain: initial access, privilege escalation, persistence, data theft, impact."],["Define operations","Triage times by severity, tuning cadence, monthly metrics (alerts, false positives, MTTD/MTTR)."],["Plan evidence","Connector status, retention settings, rule list with owners, incident tickets, tuning records."]],
 rubric:[["Log sources cover identity, M365, cloud, network, endpoints and the core application",1],["Retention meets CERT-In 180 days within India, with other requirements considered",1],["At least 8 use cases mapped to attack stages with data sources",1],["Review/tuning process with triage times and metrics",0],["Evidence plan tied to ISO 27001, SOC 2 and CERT-In",0],["Cost or volume trade-offs acknowledged",0]],
 hints:["Only sign-in logs means you'd miss mailbox rules, cloud changes and data theft.","Where are the logs stored? CERT-In says within Indian jurisdiction.","A rule nobody reviews isn't a control."],
 key:{approach:"Requirements → sources → retention → detection use cases by attack stage → operating process → evidence. Reviewers reward linking legal duties to concrete settings.",
  sample:"Sources: Entra sign-in/audit, M365 audit, Azure Activity + AWS CloudTrail, firewall (CEF), Linux syslog, payment app audit log, Defender for Endpoint. Workspace region: Central India; analytics retention 90 days + archive to 1 year (≥180 days CERT-In; 12 months SOC 2 customer contracts).\nUse cases: password spraying (SigninLogs); impossible travel (SigninLogs); new global admin (AuditLogs); MFA method added + risky sign-in (AuditLogs); inbox forwarding external (OfficeActivity); mass download (OfficeActivity); public storage change (AzureActivity/CloudTrail); disabled logging (AzureActivity/CloudTrail); payment-app admin export (app log); malware alert (Defender).\nOps: High triaged in 30 min, Medium 4h; weekly tuning review; monthly metrics to CISO; quarterly rule review.\nEvidence: connector health screenshots monthly, retention settings export, rule inventory with owners, incident tickets, tuning change log.",
  tips:["Rule to detect logging being turned off is a must-have.","Tie each use case to a business risk the board recognises."]},
 videos:[["Why: logging and monitoring requirements","CERT-In 2022 directions log retention 180 days explained"],["How: build detections with MITRE ATT&CK","Microsoft Sentinel MITRE ATT&CK coverage analytics rules"]]},

/* ---------- Compliance automation ---------- */
{id:"t-grcauto-1",topic:"t-grcauto",lvl:1,title:"Triage failing automated tests",hours:"2 hours",
 company:"LedgerLeaf, two weeks after connecting a compliance-automation tool for SOC 2.",
 problem:"The dashboard shows these failing tests. The CTO asks what each means, who should fix it, and how urgent it is.",
 objective:"For each failing test, explain it in plain words, assign an owner, set urgency and write the remediation ticket title.",
 deliverables:["A triage table: test, plain meaning, owner, urgency, ticket title, how you'll know it's fixed"],
 steps:[["Translate the test","What is it checking and why would an auditor care?"],["Pick the owner","IT for laptops and accounts, Engineering for code and cloud, HR for people tasks."],["Set urgency","Security exposure first, paperwork second."],["Write the ticket title","Specific and testable."]],
 data:{"Failing tests":[["Test","Failing items"],["MFA enabled for identity provider users","3 of 58 users"],["Laptops have disk encryption","5 of 61 devices"],["Offboarded employees removed from AWS within 3 days","1 (left 19 days ago)"],["Employees accepted security policies","11 of 58"],["Security awareness training completed in last 12 months","9 of 58"],["Production database backups enabled","1 database"],["Code changes require pull-request approval","2 repositories"]]},
 rubric:[["Each test explained correctly in plain words",1],["Sensible owners (IT, Engineering, HR/People)",1],["Ex-employee AWS access, missing MFA and backups treated as most urgent",1],["Specific ticket titles with a clear definition of done",0]],
 hints:["Which failures could let an attacker in today?","Policy acceptance and training matter for the audit but don't expose data tonight.","'Done' = the test turns green."],
 key:{approach:"Translate, assign, prioritise by real exposure, write testable tickets.",
  sample:"Leaver in AWS – Critical – IT – 'Remove AWS access for leaver (left 19 days ago) and review CloudTrail' – done when test green + log check note.\nMFA 3 users – High – IT – 'Enforce MFA for 3 users'.\nBackups prod DB – High – Engineering – 'Enable automated backups on orders-db'.\nDisk encryption 5 laptops – High – IT.\nPR approval 2 repos – Medium – Engineering – 'Enable branch protection with 1 approval on repos X, Y'.\nPolicy acceptance 11, Training 9 – Medium – People team – reminders with deadline.",
  tips:["Check whether the leaver's access was used after they left.","Group people-tasks into one campaign rather than 20 tickets."]},
 videos:[["Why: continuous control monitoring","continuous control monitoring compliance automation explained"],["How: SOC 2 with automation tools","Vanta demo SOC 2 automated tests"]]},

{id:"t-grcauto-2",topic:"t-grcauto",lvl:2,title:"One control set for SOC 2, ISO 27001 and DPDP",hours:"4 hours",
 company:"PaySetu, which needs SOC 2 for US clients, ISO 27001 for banks, and DPDP readiness.",
 problem:"Three teams were about to build three separate control lists. You're asked to build one common control set and show how each control satisfies all three, with the evidence source for each.",
 objective:"Build 12 common controls mapped to SOC 2 criteria, ISO 27001:2022 Annex A and DPDP duties, each with automated or manual evidence.",
 deliverables:["A 12-row matrix: control, SOC 2, ISO 27001, DPDP section/rule, evidence (automated test or manual upload), owner","A note on where one framework needs more than the others"],
 steps:[["Pick common ground","Access, MFA, encryption, logging, backups, vendors, training, incident response, change management, retention, data inventory, rights requests."],["Map","SOC 2 CC series, ISO Annex A numbers, DPDP sections (e.g. 8(5) safeguards, 8(6) breach intimation, 8(7) erasure, 11–13 rights) and Rules."],["Decide evidence","Which can a tool test automatically? Which need documents?"],["Note differences","DPDP has privacy duties (notice, consent, rights) SOC 2 Security doesn't cover."]],
 rubric:[["12 controls, each mapped to all three where applicable",1],["Mappings are accurate at section/criterion level",1],["Evidence type identified (automated vs manual) for each",1],["Recognises DPDP-specific duties (notice, consent, rights, breach intimation) beyond security frameworks",0],["Owners assigned",0]],
 hints:["MFA maps to SOC 2 CC6.1 and ISO A.5.17/A.8.5; for DPDP it supports 8(5) reasonable security safeguards.","Breach handling: SOC 2 CC7.3–7.5, ISO A.5.24–5.26, DPDP 8(6).","Consent and notice have no real SOC 2 Security equivalent."],
 key:{approach:"Common controls reduce duplicate work; mapping must be accurate; the gaps between frameworks are where privacy expertise shows.",
  sample:"MFA | CC6.1 | A.5.17, A.8.5 | s.8(5) | auto (IdP test) | IT\nEncryption at rest | CC6.1/6.7 | A.8.24 | s.8(5) + Rules security safeguards | auto (cloud test)\nLogging & monitoring | CC7.2 | A.8.15–8.16 | s.8(5); Rules log retention | auto + manual review records\nIncident response & notification | CC7.3–7.5 | A.5.24–5.26 | s.8(6) + Rules (Board, individuals) | manual (plan, tests, incident log)\nVendor management | CC9.2 | A.5.19–5.22 | s.8(1),(2) processor contracts | manual\nRetention & deletion | C1.2 (if Confidentiality in scope) | A.5.33, A.8.10 | s.8(7) | manual + retention config\nRights requests | – | A.5.34 | ss.11–14 | manual (DSAR log)\nNotice & consent | – | A.5.34 | ss.5–6 | manual (notice, consent records)…\nNote: DPDP adds notice, consent, rights and children's data duties; SOC 2 Security doesn't cover these unless Privacy criteria are in scope.",
  tips:["Say 'supports' rather than 'complies with' for law mappings.","Keep one evidence item feeding many frameworks."]},
 videos:[["Why: common control frameworks","common controls framework map SOC 2 ISO 27001"],["How: control mapping in practice","control mapping spreadsheet GRC tutorial"]]},

{id:"t-grcauto-3",topic:"t-grcauto",lvl:3,title:"Choose a GRC platform: requirements and vendor scoring",hours:"5–6 hours",
 company:"Ameri-India Wealth Services, a 3,000-person Indian centre of a US wealth firm, currently running GRC in spreadsheets.",
 problem:"Leadership wants a GRC platform for risk registers, control testing, SOX-style audits, vendor risk and regulatory change. Options under consideration: an enterprise platform (Archer, MetricStream, ServiceNow IRM or AuditBoard) or a compliance-automation tool (Vanta/Drata).",
 objective:"Write requirements, a weighted scoring model and a recommendation memo, including the vendor-risk and data-protection checks the platform itself must pass.",
 deliverables:["15–20 requirements grouped (must/should/could)","A weighted scoring sheet comparing tool types (use public information; don't invent prices or features)","Data protection and TPRM checks for the chosen vendor (hosting region, SOC 2, DPA, sub-processors)","A one-page recommendation with risks and implementation phases"],
 steps:[["Gather needs","Who uses it (risk, compliance, internal audit, IT), for what processes, at what scale."],["Write requirements","Must: risk register, control testing workflow, issues, audit trail, SSO/MFA, India or approved hosting. Should: regulatory change feeds, vendor portal. Could: AI assistance."],["Weight and score","Fit to needs outweighs features you won't use."],["Check the vendor itself","SOC 2/ISO reports, DPA, sub-processors, data location, exit and export."],["Recommend","Explain trade-offs: enterprise depth vs speed and automation."]],
 rubric:[["Requirements grouped by priority and tied to the firm's processes",1],["Weighted scoring model with transparent criteria",1],["Recognises enterprise GRC suits SOX/audit/risk scale while automation tools suit cloud SOC 2 evidence, without inventing facts",1],["Vendor due diligence on the platform itself (security reports, DPA, data location, exit)",1],["Implementation phases and adoption risks",0]],
 hints:["A 3,000-person regulated firm with internal audit has different needs than a SaaS start-up.","Don't make up prices or feature claims; say 'to confirm in demo/RFP'.","Exit: can you export all data in a usable format?"],
 key:{approach:"Needs → requirements → weighted scoring → vendor due diligence → recommendation and phased rollout. Reviewers reward honesty about unknowns and fit-to-context reasoning.",
  sample:"Must (weight 3): risk register with scoring, control library + testing workflow, issues and action tracking, internal audit module, full audit trail, SSO/MFA, data residency/approved region, export. Should (2): vendor risk portal, regulatory change feed, dashboards. Could (1): AI drafting.\nScoring (illustrative, to confirm in RFP): Enterprise GRC platforms score high on audit/SOX, risk and scale; compliance-automation tools score high on cloud evidence automation but low on internal audit/SOX depth.\nRecommendation: shortlist two enterprise platforms for RFP and demos; consider an automation tool later for cloud SOC 2 evidence feeding the platform.\nVendor checks: SOC 2 Type II + ISO 27001 certificate, DPA with breach notice ≤48h, sub-processor list, hosting region, encryption, export format, termination assistance.\nPhases: 1) risk & controls 2) audit 3) vendors 4) regulatory change.",
  tips:["Fit beats feature count.","Your platform is a vendor holding sensitive data; run TPRM on it."]},
 videos:[["Why: comparing GRC platforms","GRC software comparison Archer MetricStream ServiceNow AuditBoard"],["How: software selection scoring matrix","weighted scoring matrix vendor selection tutorial"]]},

/* ---------- Vulnerability management ---------- */
{id:"t-vuln-1",topic:"t-vuln",lvl:1,title:"Prioritise a vulnerability scan",hours:"2 hours",
 company:"PaySetu (payments start-up). Policy SLAs: P1 7 days, P2 30 days, P3 90 days, P4 180 days.",
 problem:"Here are eight findings from this week's scan. The IT manager asks which to fix first.",
 objective:"Assign a priority and due date to each finding using severity, active exploitation, exposure and asset importance, and explain the top three.",
 deliverables:["A table: finding, CVSS, KEV?, exposure, asset importance, priority, due date","Three sentences explaining your top three choices"],
 steps:[["Read the CVSS band","Critical 9–10, High 7–8.9, Medium 4–6.9, Low under 4."],["Check exploitation","KEV = attackers are using it now."],["Check exposure and importance","Internet-facing payment systems first; isolated test boxes later."],["Assign and date","Use the policy SLAs from the scan date (1 November)."]],
 data:{"Scan findings":[["#","Asset","Finding","CVSS","In CISA KEV","Exposure","Asset"],["1","vpn-gw","VPN appliance remote code execution","9.8","Yes","Internet","Critical"],["2","pay-api","Outdated TLS library","7.5","No","Internet","Critical"],["3","lab-07","Old Java runtime","9.8","No","Isolated lab","Low"],["4","hr-laptop-14","Browser update missing","8.8","Yes","User device","Medium"],["5","intranet","Missing security header","4.3","No","Internal","Low"],["6","db-01","Database patch missing","7.2","No","Internal (app servers only)","Critical"],["7","printer-3","Default admin password","9.8","No","Internal","Low"],["8","web-mkt","Outdated WordPress plugin","8.1","Yes","Internet","Medium"]]},
 rubric:[["Findings 1 and 8 (KEV + internet-facing) ranked P1",1],["Finding 3 (high CVSS but isolated, low-importance asset) not ranked top priority",1],["Due dates calculated from the SLA policy",0],["Finding 4 recognised as exploited in the wild, prioritised high despite being a laptop",0],["Clear reasoning for top three",0]],
 hints:["Which findings are both exploited now and reachable from the internet?","Does a 9.8 on an isolated lab machine beat a 7.5 on the payment API?","Default passwords are trivial to exploit even without a CVE in KEV."],
 key:{approach:"Score = severity × likelihood (KEV/EPSS) × exposure × asset value. Explain trade-offs, not just numbers.",
  sample:"P1 (8 Nov): #1 vpn-gw, #8 web-mkt, #4 hr-laptop-14 (KEV). P2 (1 Dec): #2 pay-api, #6 db-01, #7 printer default password (quick fix, do now anyway). P3 (30 Jan): #3 lab-07. P4: #5 intranet header.\nTop three: VPN RCE is exploited and is the front door; the WordPress plugin is exploited and public; the browser flaw is exploited and users browse daily.",
  tips:["Fix trivial things like default passwords immediately even if 'P2'.","Note your assumptions (e.g. lab is truly isolated)."]},
 videos:[["Why: risk-based vulnerability prioritisation","risk based vulnerability management CISA KEV prioritization"],["How: read a scan report","Nessus scan report explained"]]},

{id:"t-vuln-2",topic:"t-vuln",lvl:2,title:"Write a vulnerability management policy with exceptions",hours:"3–4 hours",
 company:"Kavach IT Services, preparing for ISO 27001 and client audits; RBI-regulated clients ask about patch SLAs.",
 problem:"There is no written vulnerability policy. Teams patch 'when they can', and two systems can't be patched without breaking vendor software.",
 objective:"Write a 2-page vulnerability management policy and an exception form, and fill in the form for one real-looking case.",
 deliverables:["Policy: scope, scanning frequency, prioritisation method, SLAs, roles, exceptions, reporting, coverage","Exception form template","One completed exception with compensating controls and expiry"],
 steps:[["Scope","All servers, cloud resources, laptops, network devices, internet-facing applications."],["Scanning","Authenticated internal scans at least monthly, external weekly, plus after major changes."],["Prioritise","Severity plus exploitation plus exposure plus asset value."],["SLAs and escalation","Who is told when something goes overdue?"],["Exceptions","Reason, compensating controls, risk owner approval by level, expiry, register."],["Reporting","Monthly metrics to the CISO, quarterly to the risk committee."]],
 rubric:[["Scope and scanning frequency defined, including authenticated scans",1],["Prioritisation method beyond CVSS alone",1],["SLAs with escalation for overdue items",1],["Exception process with compensating controls, approver level and expiry",1],["Completed exception example is realistic",0],["Metrics and reporting cadence",0]],
 hints:["Who approves accepting a Critical? Probably not the engineer.","An exception without an expiry becomes permanent.","What will the monthly report show?"],
 key:{approach:"Policy that is testable: an auditor can sample findings and check each against SLA, and sample exceptions and check approval and expiry.",
  sample:"SLAs: P1 7d, P2 30d, P3 90d, P4 180d from first detection; overdue P1 escalates to CISO in 24h.\nExceptions: P1/P2 approved by CISO + system owner's VP; P3/P4 by system owner; max 90 days, renewable once with re-assessment; logged in exception register.\nExample: legacy billing server (Windows 2012) can't take patch until vendor upgrade 31 Mar. Compensating: firewall allows only app-01 on port 1433, EDR in block mode, daily log review. Risk: High → Medium residual. Approved CISO + VP Finance. Expires 31 Mar.\nMetrics: % within SLA by priority, overdue count/age, KEV open, scan coverage %, active/expiring exceptions.",
  tips:["Write 'from first detection', not 'from ticket creation'.","Make coverage a metric; it exposes blind spots."]},
 videos:[["Why: vulnerability management programme","vulnerability management program policy explained"],["How: risk acceptance","vulnerability risk acceptance exception process"]]},

{id:"t-vuln-3",topic:"t-vuln",lvl:3,title:"Board vulnerability report with coverage analysis",hours:"5 hours",
 company:"PaySetu, quarterly risk committee meeting next week.",
 problem:"You have three months of scanner metrics, the asset inventory count and the exception register. The committee wants to know: are we getting better, where are we exposed, and what decisions are needed?",
 objective:"Analyse the data, calculate SLA compliance and coverage, and write a one-page board report with three charts or tables and clear asks.",
 deliverables:["Calculations: SLA compliance by priority per month, coverage %, KEV open trend","A one-page report: status, trends, top risks, decisions needed","Notes on data quality issues"],
 steps:[["Calculate SLA %","Fixed within SLA ÷ total due in the month."],["Calculate coverage","Assets scanned ÷ assets in inventory."],["Read exceptions","Expired? Approved at the right level?"],["Find the story","What is improving, what is getting worse, why."],["Write for the board","Status first, then decisions they must make."]],
 data:{"Monthly metrics":[["Month","P1 due","P1 fixed in SLA","P2 due","P2 fixed in SLA","KEV open at month end","Assets scanned","Assets in inventory"],["Aug","10","6","40","31","5","410","430"],["Sep","8","7","35","30","3","415","470"],["Oct","12","11","44","39","4","418","520"]],
  "Exception register":[["ID","System","Priority","Approved by","Expiry"],["EX-01","billing-legacy","P1","CISO + VP Finance","31 Mar"],["EX-02","hr-portal","P2","System owner","none"],["EX-03","old-crm","P1","IT engineer","30 Sep"]]},
 rubric:[["SLA percentages calculated correctly (P1: 60%, 88%, 92%; P2: 78%, 86%, 89%)",1],["Coverage calculated and declining trend identified (95%, 88%, 80%) as the key concern",1],["Exception issues found: EX-02 no expiry, EX-03 expired and approved at wrong level",1],["Board report leads with status and decisions needed",0],["Data quality caveats noted (e.g. inventory growth from new cloud accounts)",0]],
 hints:["SLA performance is improving, but what is happening to coverage?","Who should approve a P1 exception? When did EX-03 expire?","Inventory jumped by 90 assets. Where might they be from?"],
 key:{approach:"Numbers first, then the story: improving fix rates hide shrinking visibility. Boards need a clear status and specific decisions.",
  sample:"P1 in SLA: Aug 60%, Sep 88%, Oct 92%. P2: 78%, 86%, 89%. Coverage: 95% → 88% → 80% (102 assets unscanned in Oct). KEV open: 5 → 3 → 4.\nStatus: Amber. Fix speed improved strongly, but one in five assets is now unscanned, mostly new cloud resources, so true exposure is unknown.\nExceptions: EX-02 has no expiry (set 90 days); EX-03 expired 30 Sep and was approved by an engineer, not CISO – re-approve or fix now.\nDecisions: 1) mandate automatic scanner enrolment for new cloud accounts (owner: Cloud Lead, 30 days); 2) approve or reject EX-03 today; 3) target 95% coverage by year end.",
  tips:["Never report fix rates without coverage.","Ask the board for decisions, not admiration."]},
 videos:[["Why: vulnerability metrics for boards","vulnerability management metrics board reporting"],["How: Excel percentage and trend charts","Excel percentage calculation line chart tutorial"]]}
];
